(function ($) {
  if (!$) return;
  var trees = {};

  function normalize(raw, setting) {
    var nodes = raw && raw.code === 1 ? raw.data : raw;
    if (setting && setting.async && typeof setting.async.dataFilter === "function") {
      nodes = setting.async.dataFilter(null, null, raw);
    }
    if (Array.isArray(nodes)) return nodes;
    return nodes ? [nodes] : [];
  }

  function nodeId(node) {
    return node.rpId || node.nodeId || node.id;
  }

  function nodeName(node) {
    return node.reportName || node.nodeName || node.name || node.text || node.title || ("Node " + nodeId(node));
  }

  function flatten(nodes, out) {
    (nodes || []).forEach(function (node) {
      out.push(node);
      if (Array.isArray(node.children)) flatten(node.children, out);
    });
    return out;
  }

  function render($el, nodes, setting, state) {
    $el.empty().addClass("ztree");
    state.nodes = flatten(nodes, []);
    if (!state.checked.length) state.checked = state.nodes.slice();

    function build(list) {
      var $ul = $("<ul></ul>");
      (list || []).forEach(function (node) {
        var id = nodeId(node);
        var $li = $('<li class="level0"></li>').attr("data-node-id", id);
        var $a = $('<a href="javascript:;" class="level0"></a>');
        if (setting.check && setting.check.enable) {
          var $checkbox = $('<input type="checkbox" class="ztree-check" checked="checked">');
          $checkbox.on("click", function (event) {
            event.stopPropagation();
            if (this.checked) {
              if (state.checked.indexOf(node) === -1) state.checked.push(node);
            } else {
              state.checked = state.checked.filter(function (item) { return item !== node; });
            }
          });
          $a.append($checkbox);
        }
        $a.append('<span class="button ico_docu"></span>');
        $a.append($("<span class='node_name'></span>").text(nodeName(node)));
        $a.on("click", function () {
          state.selected = [node];
          $el.find("a.curSelectedNode").removeClass("curSelectedNode");
          $a.addClass("curSelectedNode");
          if (setting.callback && typeof setting.callback.beforeClick === "function") {
            setting.callback.beforeClick($el.attr("id"), node);
          }
          if (setting.callback && typeof setting.callback.onClick === "function") {
            setting.callback.onClick(null, $el.attr("id"), node);
          }
        });
        $li.append($a);
        var children = build(node.children || []);
        if (children.children().length) $li.append(children);
        $ul.append($li);
      });
      return $ul;
    }

    $el.append(build(nodes).children());
  }

  $.fn.zTree = {
    init: function ($el, setting, zNodes) {
      setting = setting || {};
      var id = $el.attr("id");
      var state = { selected: [], checked: [], nodes: [] };
      var tree = {
        getSelectedNodes: function () { return state.selected; },
        getCheckedNodes: function (checked) {
          if (checked === false) {
            return state.nodes.filter(function (node) { return state.checked.indexOf(node) === -1; });
          }
          return state.checked;
        },
        cancelSelectedNode: function () {
          state.selected = [];
          $el.find("a.curSelectedNode").removeClass("curSelectedNode");
        },
        selectNode: function (node) {
          state.selected = [node];
        },
        reAsyncChildNodes: function () {
          load();
        },
        expandAll: function () {}
      };
      trees[id] = tree;

      function load() {
        if (setting.async && setting.async.url) {
          $.ajax({
            url: setting.async.url,
            type: setting.async.type || "get",
            dataType: "json",
            success: function (raw) {
              render($el, normalize(raw, setting), setting, state);
              if (setting.callback && typeof setting.callback.onAsyncSuccess === "function") {
                setting.callback.onAsyncSuccess(null, id, null, raw);
              }
            }
          });
        }
      }

      if (zNodes) render($el, normalize(zNodes, setting), setting, state);
      else load();
      return tree;
    },
    getZTreeObj: function (id) {
      return trees[id];
    }
  };
})(window.jQuery || window.layui && window.layui.$);
